css:
.stage{position:relative; overflow:visible}         /* hiddenだと成立しない */
.stage .mask{overflow:hidden; border-radius:50%/40%} /* 楕円・アーチ側だけ切る */
.stage .cutout{position:absolute; z-index:2; filter:none; pointer-events:none}
.cutout.tl{top:-2%;   left:22%;  width:14%}
.cutout.br{right:-4%; bottom:-70px; width:34%}

/* マスクの中身をベタ面にして人物だけ外へ出す版 */
.mask{background:linear-gradient(160deg,#ffd23f,#8a6bd6 55%,#ff5fa2)}
.mask img{position:absolute; left:-10%; bottom:0; width:120%}

/* グラフ・図の縁をまたがせる版 */
.ring{position:relative; overflow:visible; z-index:1}
.ring .cutout{left:50%; bottom:-70px; translate:-50% 0; width:52%; z-index:2}

/* 円の輪郭線を"枠"でなく飾り罫に落とす版 */
.circ{position:relative; width:200px; aspect-ratio:1;
  border:1.5px solid #7fa392; border-radius:50%; overflow:visible}
.circ img{position:absolute; top:-6%; left:-8%; width:120%; max-width:none}
